PRAGMA foreign_keys = ON;
CREATE TABLE accounts (id TEXT PRIMARY KEY, platform TEXT NOT NULL CHECK(platform IN ('instagram','tiktok')), handle TEXT NOT NULL, product_id TEXT, source_url TEXT, destination INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, locale TEXT NOT NULL DEFAULT 'ja-JP', settings_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE source_posts (id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id), platform_post_id TEXT, source_url TEXT NOT NULL, caption TEXT, rights_status TEXT NOT NULL DEFAULT 'pending' CHECK(rights_status IN ('pending','owned','licensed','permitted','blocked')), media_key TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', ingested_at TEXT NOT NULL);
CREATE TABLE clips (id TEXT PRIMARY KEY, source_post_id TEXT NOT NULL REFERENCES source_posts(id), media_key TEXT, start_ms INTEGER NOT NULL, end_ms INTEGER NOT NULL, tags_json TEXT NOT NULL DEFAULT '[]', features_json TEXT NOT NULL DEFAULT '{}', transcript TEXT, quality_score REAL, created_at TEXT NOT NULL);
CREATE TABLE creatives (id TEXT PRIMARY KEY, product_id TEXT REFERENCES products(id), account_id TEXT REFERENCES accounts(id), angle TEXT NOT NULL, hook TEXT, caption TEXT, status TEXT NOT NULL CHECK(status IN ('generating','qa','pending_approval','approved','rejected','regenerate','publishing','published','failed')), media_key TEXT, recipe_json TEXT NOT NULL, qa_json TEXT NOT NULL DEFAULT '{}', scheduled_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE creative_clips (creative_id TEXT NOT NULL REFERENCES creatives(id), clip_id TEXT NOT NULL REFERENCES clips(id), position INTEGER NOT NULL, trim_start_ms INTEGER NOT NULL DEFAULT 0, trim_end_ms INTEGER, PRIMARY KEY(creative_id, position));
CREATE TABLE publications (id TEXT PRIMARY KEY, creative_id TEXT NOT NULL REFERENCES creatives(id), account_id TEXT NOT NULL REFERENCES accounts(id), platform TEXT NOT NULL, status TEXT NOT NULL, platform_post_id TEXT, post_url TEXT, error TEXT, published_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE metrics (id TEXT PRIMARY KEY, publication_id TEXT NOT NULL REFERENCES publications(id), captured_at TEXT NOT NULL, views INTEGER, reach INTEGER, watch_time_ms INTEGER, avg_watch_ms INTEGER, likes INTEGER, saves INTEGER, shares INTEGER, comments INTEGER, raw_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE jobs (id TEXT PRIMARY KEY, type TEXT NOT NULL, entity_id TEXT, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, payload_json TEXT NOT NULL DEFAULT '{}', error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_creatives_queue ON creatives(status, scheduled_at, created_at);
CREATE INDEX idx_clips_source ON clips(source_post_id);
CREATE INDEX idx_metrics_publication ON metrics(publication_id, captured_at);
